solution.Solution.cs:
using System.Reflection;

[AttributeUsage(AttributeTargets.Property)]
public sealed class RequiredAttribute : Attribute { }

[AttributeUsage(AttributeTargets.Property)]
public sealed class RangeAttribute : Attribute
{
    public RangeAttribute(int min, int max) => (Min, Max) = (min, max);
    public int Min { get; }
    public int Max { get; }
}

public static class Validator
{
    public static List<string> Check(object obj)
    {
        var problems = new List<string>();
        foreach (var p in obj.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance))
        {
            object? value = p.GetValue(obj);
            if (p.GetCustomAttribute<RequiredAttribute>() is not null &&
                (value is null || value is string s && string.IsNullOrWhiteSpace(s)))
            {
                problems.Add($"{p.Name} is required");
            }
            if (p.GetCustomAttribute<RangeAttribute>() is { } range && value is int n && (n < range.Min || n > range.Max))
            {
                problems.Add($"{p.Name} must be between {range.Min} and {range.Max}");
            }
        }
        return problems;
    }
}

unitTests:
Test("problems are reported", () =>
{
    CheckEq(Validator.Check(new SignUp { Name = " ", Age = 7 }), new[] { "Name is required", "Age must be between 13 and 120" });
    CheckEq(Validator.Check(new SignUp { Name = null, Age = 121 }), new[] { "Name is required", "Age must be between 13 and 120" });
});

Test("valid objects", () =>
{
    CheckEq(Validator.Check(new SignUp { Name = "Ada", Age = 13 }).Count, 0);
    CheckEq(Validator.Check(new Settings { Volume = 10 }).Count, 0);
    CheckEq(Validator.Check(new Settings { Volume = 11, Theme = "" }), new[] { "Theme is required", "Volume must be between 0 and 10" });
});

Test("attribute usage", () =>
{
    var usage = typeof(RangeAttribute).GetCustomAttributes(typeof(AttributeUsageAttribute), false).Cast<AttributeUsageAttribute>().FirstOrDefault();
    Check(usage is not null && usage.ValidOn == AttributeTargets.Property, "mark the attributes with [AttributeUsage(AttributeTargets.Property)]");
});

